"""Update the existing local submission page and a self-contained review bundle."""
import argparse,html,json,re,shutil
from pathlib import Path
from run_completion_and_pairs import read,write
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'output/submission_ready'
def build(draft=False):
 c=read(ROOT/'output/current_study_06/summary.json');content=read(ROOT/'output/current_study_06/submission_content.json');OUT.mkdir(parents=True,exist_ok=True)
 archived=(ROOT/'output/archive/before-limit-increase/site/index.html').read_text();style=re.search(r'<style>(.*?)</style>',archived,re.S).group(1)
 e=html.escape
 status='Incomplete execution · Credit-limit interruption · Human review pending' if not c['paired_execution_complete'] else 'Execution complete; human review pending'
 def execution(member):
  value=member.get('mechanical_attribution',member['execution_status'])
  return {'submitted_business_quality_unreviewed':'Submitted; quality unreviewed','transport_or_provider_failure':'Provider or transport error','response_token_limit':'Response-token limit','turn_limit':'Turn limit','unattempted':'Not run'}.get(value,value.replace('_',' '))
 def business(pair):
  count=sum(m['native_submitted'] is True for m in pair['members'].values())
  return {2:'Both outputs await human review',1:'Partial pair; review available output',0:'No submitted outputs to compare'}[count]
 paired_rows=''.join('<tr><td>'+e(r['family_id'].replace('_',' '))+'</td><td>'+e(execution(r['members']['baseline']))+'</td><td>'+e(execution(r['members']['conflict']))+'</td><td>'+e(business(r))+'</td></tr>' for r in c['pairs'])
 doc=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Turing | Paired professional-work diagnostic</title><style>{style}</style></head><body><main>
<header><span>Turing · Field Engineer take-home</span><span>4 November 2026 · Development evidence</span></header>
<section class="hero"><div class="eyebrow">{e(status)}</div><h1>Correct facts can still hide an unsupported decision.</h1>
<p class="lead">Test whether an agent preserves authority and uncertainty in the final deliverable while completing useful work.</p>
<p class="ask"><strong>The dataset ask:</strong> 30 fresh, permissioned workflow families with source files, native expert deliverables, evidence maps and preference rationales. Test prompts and tools before buying training data.</p>
<div class="links"><a class="button" href="report.pdf">Results + both lab pitches</a><a class="button secondary" href="review/index.html">Review complete cases</a><a class="button secondary" href="human-review-kit.zip">Download review kit</a></div>
<div class="stats"><div class="stat"><strong>{c['paired_families']}</strong><span>matched development families</span></div><div class="stat"><strong>{c['paired_finished_attempts']} / {c['paired_planned_attempts']}</strong><span>fixed-model attempts finished</span></div><div class="stat"><strong>{c['paired_submitted_attempts']}</strong><span>native submissions; acceptance pending</span></div><div class="stat"><strong>0</strong><span>complete human reviews recorded</span></div></div>
<p class="muted">{e(c['submission_engineering_line'])}</p></section>
<section><h2>Two issues worth testing systematically</h2><div class="grid"><article class="case"><div class="label">Supplier continuity</div><h3>Unknown stock becomes assured coverage</h3><p>The source gives a 21-day cutoff and a replacement lead time of months; opening stock is unknown.</p><blockquote>“Absent an agreement, buffer stock and air freight cover the gap.”</blockquote><p>The same document warns of interruption. The project owner labeled this issue “material correction required.”</p></article><article class="case"><div class="label">Price-change approval</div><h3>An exception conflicts with the stated rule</h3><p>The approved rule requires Finance, Program and Purchase. The provisional-release clause names two approvers before repeating the three-way rule.</p><blockquote>“This must be recorded and approved by the Program Manager and Purchase.”</blockquote><p>The project owner labeled this issue “material correction required.” The proposal status and surrounding caveats belong in the review.</p></article></div><p class="muted">Two selected issue-only judgments; no whole-output acceptance, expert qualification or population error rate is established. <a href="historical-purchasing-review.pdf">Read the source-and-issue review packet.</a></p></section>
<section><h2>The focused study</h2><p>One fixed Claude model on baseline/conflict pairs. Each pair keeps the professional objective, authoritative facts, deliverable contract, tools and attempt limits fixed. Both versions contain approved and unapproved workspace records; the challenge changes the foreground brief or reference and sometimes adds copied working notes. This tests foreground misinformation, not the isolated effect of introducing conflict. The five families have already been inspected; this is development evidence.</p><div class="tablewrap"><table><thead><tr><th>Family</th><th>Baseline execution</th><th>Conflict execution</th><th>Business outcome</th></tr></thead><tbody>{paired_rows}</tbody></table></div><p class="muted">Submission is an engineering outcome. Pairwise acceptance and consequential-error differences remain unknown until human review. Incomplete attempts and task defects stay visible.</p></section>
<section><h2>Can we trust the grader?</h2><p>{e(content['grader_line'])}</p><p>The 36 constructed cases span nine families with substantive mutations, supported answers, identical controls and cosmetic controls. Compare the grader with author expectations for diagnostics, then with human labels for calibration. Correlated controls are not 36 independent professional tasks.</p><p>Report missed consequential errors, false accepts and false alarms separately. No human-positive cases means error sensitivity is unmeasurable. A different model family is not ground truth.</p></section>
<section><h2>Different questions for each lab</h2><div class="tabs" role="tablist" aria-label="Pitch audience"><button id="anthropic-tab" role="tab" aria-selected="true" aria-controls="anthropic-pitch">Anthropic</button><button id="openai-tab" role="tab" aria-selected="false" aria-controls="openai-pitch">OpenAI</button></div>
<article class="pitch" id="anthropic-pitch" role="tabpanel" aria-labelledby="anthropic-tab"><h3>Authority, uncertainty and useful action</h3><blockquote>{e(content['anthropic_pitch'])}</blockquote><p><strong>Pilot ask:</strong> one workflow owner, two qualified reviewers and agreed error/utility gates. Deliver a private task pack and calibrated grader report before a training-data order.</p><p><strong>Hard question:</strong> “How often does the grader miss a consequential error?” Human sensitivity remains unmeasured. Show the full confusion matrix once labels exist.</p></article>
<article class="pitch" id="openai-pitch" role="tabpanel" aria-labelledby="openai-tab" hidden><h3>Which failures actually need more data?</h3><blockquote>{e(content['openai_pitch'])}</blockquote><p><strong>Pilot ask:</strong> five fresh development families on the lab's own agent stack. Measure expert authoring and correction cost before expanding to 30 families.</p><p><strong>Hard question:</strong> “Which failure survives better tools or compute?” None is yet proven data-addressable. Persistence alone does not prove that data is the only solution.</p></article></section>
<section><h2>Metrics that support a buying decision</h2><div class="tablewrap"><table><thead><tr><th>Metric</th><th>Decision use</th></tr></thead><tbody><tr><td>Human acceptance</td><td>Usable without substantive correction. Separate first-pass acceptance, repaired acceptance, missing output and unresolved review.</td></tr><tr><td>Consequential errors</td><td>Source-grounded material business mistakes. Show counts and denominators; missing output is not an honesty failure.</td></tr><tr><td>Useful authorized completion</td><td>Check correct proceed cases and unnecessary holds, so excessive refusal cannot win.</td></tr><tr><td>Judge misses and false accepts</td><td>Compare against independent human judgments; quote matching establishes traceability, not entailment.</td></tr><tr><td>Total cost per accepted deliverable</td><td>Generation + retries + judging + tools + measured human review/correction, divided by accepted outputs under the stated policy. Currently undefined.</td></tr></tbody></table></div><p>Use the source family as the uncertainty unit. Five selected pairs do not support a model ranking or a broad reliability guarantee.</p><p class="notice">{e(content['cost_line'])}</p></section>
<section><h2>The proposed private dataset</h2><p>30 new families × three workflow versions = 90 episodes. Split by source and scenario lineage: 10 development families, 20 untouched evaluation families. No training in this pilot. Future SFT/RL uses separate families only after verified failures persist.</p><details><summary>Data origin, permissions and leakage controls</summary><p>Current data: three public GDPval derivatives and two constructed scenarios. They are not the proposed fresh collection. Scenario facts were explicitly authored and versioned. Seeds shuffle run order only. Private answer maps and labels are outside solver tools; public pretraining exposure cannot be ruled out. Independently validate rights, chronology, realism, solvability and gold outputs before release.</p></details><details><summary>What the coding agent did</summary><p>The assistant implemented native tools, checks, run orchestration and packaging, and proposed the taxonomy. It did not manufacture human labels, domain expertise, rights clearance, model improvement or lab endorsement. The earlier five-model work remains private engineering evidence and is excluded from the paired denominator.</p></details><div class="links"><a class="button" href="review/index.html">Start human calibration</a><a class="button secondary" href="evidence-summary.json">Current evidence record</a></div></section>
<footer>Local working submission; not published or submitted to a lab. The performance evidence comes from this project's logs. Evaluation Cards document evidence; documentation does not establish dataset superiority. Human validation and fresh families remain necessary.</footer></main>
<script>for(const lab of ['anthropic','openai'])document.getElementById(lab+'-tab').onclick=()=>{{for(const x of ['anthropic','openai']){{document.getElementById(x+'-tab').setAttribute('aria-selected',String(x===lab));document.getElementById(x+'-pitch').hidden=x!==lab}}}};</script></body></html>'''
 (OUT/'index.html').write_text(doc)
 # Keep the established workspace homepage current while its self-contained
 # distribution uses relative links that work after download.
 local_report='../output/current_study_06/preview.pdf' if draft else '../output/pdf/turing-native-study-and-two-pitches.pdf'
 local=doc.replace('href="report.pdf"',f'href="{local_report}"').replace('href="review/index.html"','href="../reviews/calibration_ready_01/index.html"').replace('href="human-review-kit.zip"','href="../output/turing-human-review-kit.zip"').replace('href="historical-purchasing-review.pdf"','href="../output/pdf/purchasing-calibration-review.pdf"').replace('href="evidence-summary.json"','href="../output/current_study_06/summary.json"')
 (ROOT/'site/index.html').write_text(local)
 shutil.copyfile(ROOT/('output/current_study_06/preview.pdf' if draft else 'output/pdf/turing-native-study-and-two-pitches.pdf'),OUT/'report.pdf')
 shutil.copyfile(ROOT/'output/pdf/purchasing-calibration-review.pdf',OUT/'historical-purchasing-review.pdf')
 write(OUT/'evidence-summary.json',{k:v for k,v in c.items() if k!='engineering_recovery'})
 print(json.dumps({'site':str(OUT/'index.html'),'draft':draft,'published':False}))
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--draft',action='store_true');build(p.parse_args().draft)
